VALUES (26811, 'tt0059125', NULL, 'Dr. Terror''s House of Horrors', 'Dr. Terror''s House of Horrors', 'movie', 1965, 'https://image.tmdb.org/t/p/w500/ccQtFSAGievlTYpuS88PCTHzLu7.jpg', 'https://image.tmdb.org/t/p/original/lX9j2uDbhJONuhQqUFjcRPQB6Ja.jpg', 'Five train passengers are joined by a mysterious fortuneteller who offers to read Tarot. A quintet of stories unfold: an architect returns to his ancestral home to find a vengeful werewolf; a doctor suspects his new wife is a vampire; an intelligent vine takes over a house; a jazz musician plagiarises music from a voodoo ceremony; and a pompous art critic is pursued by a disembodied hand.', NULL, NULL, 2.741, 6.5, 0, 11.525, '2026-10-31 20:20:27', '2026-10-31 20:20:27')
