VALUES (10552, 'tt0088889', NULL, 'Cat''s Eye', 'Cat''s Eye', 'movie', 1985, 'https://image.tmdb.org/t/p/w500/kKyq7izpMkmr8sT2nLic5qAuJPo.jpg', 'https://image.tmdb.org/t/p/original/59ydwHREhqXB8iIZo79Laaluvr1.jpg', 'Three short stories linked by a stray cat that roams from one tale to the next, in this creepy triptych that begins as Dick tries to quit smoking by any means necessary. Next, we meet Johnny, an adulterous man who''s forced by his lover''s husband onto a building''s hazardous ledge. Finally, Amanda is threatened by an evil gnome who throws suspicion on the family cat.', NULL, NULL, 4.0681, 6.761, 0, 10.52, '2026-10-31 20:20:27', '2026-10-31 20:20:27')
