VALUES (348, 'tt0078748', NULL, 'Alien', 'Alien', 'movie', 1979, 'https://image.tmdb.org/t/p/w500/vfrQk5IPloGg1v9Rzbh2Eg3VGyM.jpg', 'https://image.tmdb.org/t/p/original/AmR3JG1VQVxU8TfAvljUhfSFUOx.jpg', 'During its return to the earth, commercial spaceship Nostromo intercepts a distress signal from a distant planet. When a three-member team of the crew discovers a chamber containing thousands of eggs on the planet, a creature inside one of the eggs attacks an explorer. The entire crew is unaware of the impending nightmare set to descend upon them when the alien parasite planted inside its unfortunate host is birthed.', NULL, NULL, 33.8894, 8.175, 0, 7.69269863013698653e+01, '2026-07-15 12:01:52', '2026-10-31 20:20:27')
