VALUES (97, 'tt0084827', NULL, 'Tron', 'Tron', 'movie', 1982, 'https://image.tmdb.org/t/p/w500/jigY9B6TKz4qlfikZcd18qtzTK4.jpg', 'https://image.tmdb.org/t/p/original/vUmeBHiGp5r2ydd8aEvbNLamTVD.jpg', 'When brilliant video game maker Flynn hacks the mainframe of his ex-employer, he is beamed inside an astonishing digital world and becomes part of the very game he is designing. In his mission through cyberspace, Flynn matches wits with a maniacal Master Control Program and teams up with Tron, a security measure created to bring balance to the digital environment.', NULL, NULL, 7.4024, 6.624, 0, 24.9235, '2026-07-15 12:01:52', '2026-10-31 20:20:27')
