VALUES (500664, 'tt6499752', NULL, 'Upgrade', 'Upgrade', 'movie', 2018, 'https://image.tmdb.org/t/p/w500/woLGROUdPWdBnLVFKYdGD3kFkPY.jpg', 'https://image.tmdb.org/t/p/original/oiPUcD1IIZrYGTSIpvTmd3dRmPo.jpg', 'A brutal mugging leaves Grey Trace paralyzed in the hospital and his beloved wife dead. A billionaire inventor soon offers Trace a cure — an artificial intelligence implant called STEM that will enhance his body. Now able to walk, Grey finds that he also has superhuman strength and agility — skills he uses to seek revenge against the thugs who destroyed his life.', NULL, NULL, 8.5483, 7.517, 0, 3.23626923076923063e+01, '2026-07-20 04:02:06', '2026-10-31 20:20:27')
