VALUES (16869, 'tt0361748', NULL, 'Inglourious Basterds', 'Inglourious Basterds', 'movie', 2009, 'https://image.tmdb.org/t/p/w500/aupnPtagH9JVBuMrGEanf4iqXEQ.jpg', 'https://image.tmdb.org/t/p/original/hwNtEmmugU5Yd7hpfprNWI0DGIn.jpg', 'In Nazi-occupied France during World War II, a group of Jewish-American soldiers known as "The Basterds" are chosen specifically to spread fear throughout the Third Reich by scalping and brutally killing Nazis. The Basterds, lead by Lt. Aldo Raine soon cross paths with a French-Jewish teenage girl who runs a movie theater in Paris which is targeted by the soldiers.', NULL, NULL, 28.3515, 8.217, 0, 19.3925, '2026-07-20 04:02:06', '2026-10-31 20:20:27')
