VALUES (9383, 'tt0164052', NULL, 'Hollow Man', 'Hollow Man', 'movie', 2000, 'https://image.tmdb.org/t/p/w500/sd3qUIv5uoP2oTbqv66CzXSPjKG.jpg', 'https://image.tmdb.org/t/p/original/g6UIASElC5M6jwtV4TZlz1sok3h.jpg', 'Cocky researcher Sebastian Caine is working on a project to make living creatures invisible. Determined to achieve the ultimate breakthrough, Caine pushes his team to move to the next phase — using himself as the subject. The test is a success, but when the process can''t be reversed and Caine seems doomed to future without flesh, he starts to turn increasingly dangerous.', NULL, NULL, 9.5737, 5.97, 0, 12.374, '2026-08-12 02:31:31', '2026-10-31 20:20:27')
